import axios from 'axios';
import { cloneDeep } from 'lodash-es';

export class VAxios {
  private axiosInstance;
  private readonly options;
  constructor(options) {
    this.options = options;
    this.axiosInstance = axios.create(options);
    this.setupInterceptors();
  }
  private getTransform() {
    const { transform } = this.options;
    return transform;
  }
  private setupInterceptors() {
    const transform = this.getTransform();
    if (transform && transform.requestInterceptors) {
      this.axiosInstance.interceptors.request.use((config) => transform.requestInterceptors(config, this.options));
    }
  }
  uploadFile(config, params) {
    const formData = new window.FormData();
    formData.append(params.name || 'file', params.file);
    return this.axiosInstance.request({ ...config, method: 'POST', data: formData });
  }
  supportFormData(config) {
    return config;
  }
  get(config, options) {
    return this.request({ ...config, method: 'GET' }, options);
  }
  post(config, options) {
    return this.request({ ...config, method: 'POST' }, options);
  }
  put(config, options) {
    return this.request({ ...config, method: 'PUT' }, options);
  }
  delete(config, options) {
    return this.request({ ...config, method: 'DELETE' }, options);
  }
  request(config, options) {
    let conf = cloneDeep(config);
    const transform = this.getTransform();
    const { requestOptions } = this.options;
    const opt = Object.assign({}, requestOptions, options);
    const { beforeRequestHook } = transform || {};
    if (beforeRequestHook) {
      conf = beforeRequestHook(conf, opt);
    }
    conf.requestOptions = opt;
    conf = this.supportFormData(conf);
    return this.axiosInstance.request(conf);
  }
}

import { VAxios } from './http/Axios';

const http = new VAxios({ transform: {}, requestOptions: { joinPrefix: true } });

export const list = () => http.get({ url: '/user/list' });
export const byPage = () => http.get({ url: '/user/list', params: { pageNo: 1 } }, { joinTime: false });
export const add = (params) => http.post({ url: '/user/add', params });
export const elsewhere = () => http.get({ url: '/user/list' }, { apiUrl: '/other' });
export const unread = (o) => http.get({ url: '/user/list' }, o);

